using JetBrains.Annotations;using System;using System.Collections.Generic;using System.IO;using System.Net;using System.Threading.Tasks;using UnityEngine;using UnityEngine.Events;public class ABUpdateMgr : MonoBehaviour{    private static ABUpdateMgr instance;    private Dictionary&lt;string, ABInfo&gt; remoteABInfo = new Dictionary&lt;string, ABInfo&gt;();    private List&lt;string&gt; downLoadList = new List&lt;string&gt;();//&#x5F85;&#x4E0B;&#x8F7D;&#x7684;AB&#x5305;&#x6587;&#x4EF6;&#x540D;&#x5B57;&#x5217;&#x8868;    public static ABUpdateMgr Instance    {        get        {            if (instance == null)            {                GameObject obj = new GameObject(&quot;ABUpdateMgr&quot;);                instance = obj.AddComponent&lt;ABUpdateMgr&gt;();            }            return instance;        }    }    public void DownLoadABCompareFile()    {        print(Application.persistentDataPath);        //1.&#x4ECE;&#x8D44;&#x6E90;&#x670D;&#x52A1;&#x5668;&#x4E0B;&#x8F7D;&#x8D44;&#x6E90;&#x5BF9;&#x6BD4;&#x6587;&#x4EF6;        DownLoadFile(&quot;ABCompareInfo.txt&quot;, Application.persistentDataPath + &quot;/ABCompareInfo.txt&quot;);        //2.&#x83B7;&#x53D6;&#x8D44;&#x6E90;&#x5BF9;&#x6BD4;&#x6587;&#x4EF6;&#xFF0C;&#x8FDB;&#x884C;&#x5B57;&#x7B26;&#x4E32;&#x8FDB;&#x884C;&#x62C6;&#x5206;        string info = File.ReadAllText(Application.persistentDataPath + &quot;/ABCompareInfo.txt&quot;);        string[] strs = info.Split(&apos;|&apos;);        string[] infos = null;        for (int i = 0; i &lt; strs.Length; i++)        {            infos = strs[i].Split(&apos; &apos;);            //&#x8BB0;&#x5F55;&#x6BCF;&#x4E00;&#x4E2A;&#x8FDC;&#x7AEF;AB&#x5305;&#x7684;&#x4FE1;&#x606F;            remoteABInfo.Add(infos[0], new ABInfo(infos[0], infos[1], infos[2]));        }    }    //&#x5B58;&#x50A8;&#x8FDC;&#x7AEF;AB&#x5305;&#xFF0C;&#x4E4B;&#x540E;&#x548C;&#x672C;&#x5730;&#x8FDB;&#x884C;&#x5BF9;&#x6BD4;    public async void DownLoadABFile(UnityAction&lt;bool&gt; overCallBack, UnityAction&lt;int, int&gt; UpdatePro)    {        //1.&#x904D;&#x5386;&#x5B57;&#x5178;&#x7684;&#x952E;&#xFF0C;&#x6839;&#x636E;&#x6587;&#x4EF6;&#x540D;&#xFF0C;&#x4E0B;&#x8F7D;AB&#x5305;&#x5230;&#x672C;&#x5730;        foreach (string name in remoteABInfo.Keys)        {            downLoadList.Add(name);        }        //&#x672C;&#x5730;&#x5B58;&#x50A8;&#x8DEF;&#x5F84;&#xFF0C;&#x7531;&#x4E8E;&#x591A;&#x7EBF;&#x7A0B;&#x4E0D;&#x80FD;&#x8BBF;&#x95EE;Unity&#x76F8;&#x5173;&#x7684;&#x4E00;&#x4E9B;&#x5185;&#x5BB9;&#xFF0C;&#x6240;&#x4EE5;&#x653E;&#x5728;&#x5916;&#x90E8;        string localPath = Application.persistentDataPath + &quot;/&quot;;        //&#x8BB0;&#x5F55;&#x4E0B;&#x8F7D;&#x6210;&#x529F;&#x7684;&#x6587;&#x4EF6;&#x540D;&#x7684;&#x5217;&#x8868;        List&lt;string&gt; tempList = new List&lt;string&gt;();        //&#x662F;&#x5426;&#x4E0B;&#x8F7D;&#x6210;&#x529F;        bool isOver = false;        //&#x91CD;&#x65B0;&#x4E0B;&#x8F7D;&#x7684;&#x6700;&#x5927;&#x6B21;&#x6570;        int downloadNum = 5;        //&#x4E0B;&#x8F7D;&#x6210;&#x529F;&#x7684;&#x6587;&#x4EF6;&#x6570;&#x91CF;        int downLoadOverNum = 0;        //&#x8FD9;&#x4E00;&#x6B21;&#x9700;&#x8981;&#x4E0B;&#x8F7D;&#x7684;&#x6587;&#x4EF6;&#x603B;&#x6570;&#x91CF;        int downLoadMaxNum = downLoadList.Count;        while (downLoadList.Count &gt; 0 &amp;&amp; downloadNum &gt; 0)        {            for (int i = 0; i &lt; downLoadList.Count; i++)            {                await Task.Run(() =&gt;                {                    isOver = DownLoadFile(downLoadList[i], localPath + downLoadList[i]);                }                );                if (isOver)                {                    UpdatePro(++downLoadOverNum, downLoadMaxNum);                    tempList.Add(downLoadList[i]);                }            }            //&#x628A;&#x4E0B;&#x8F7D;&#x6210;&#x529F;&#x7684;&#x6587;&#x4EF6;&#x540D;&#x4ECE;&#x4E0B;&#x8F7D;&#x5217;&#x8868;&#x4E2D;&#x79FB;&#x9664;            //&#x4E5F;&#x53EF;&#x4EE5;&#x8BA9;&#x5012;&#x7740;&#x904D;&#x5386;&#x4E0B;&#x8F7D;&#x5217;&#x8868;&#xFF0C;&#x4E0B;&#x8F7D;&#x4E00;&#x4E2A;&#x5C31;&#x79FB;&#x9664;&#x4E00;&#x4E2A;&#xFF0C;&#x5C31;&#x4E0D;&#x9700;&#x8981;&#x4E34;&#x65F6;&#x5217;&#x8868;&#x7684;&#x8F85;&#x52A9;            for (int i = 0; i &lt; tempList.Count; i++) downLoadList.Remove(tempList[i]);            downloadNum--;        }        overCallBack(downLoadList.Count == 0);//&#x544A;&#x8BC9;&#x5916;&#x90E8;&#xFF0C;&#x4E0B;&#x8F7D;&#x6210;&#x529F;    }    private bool DownLoadFile(string fileName, string localPath)    {        try        {            //1.&#x521B;&#x5EFA;FTP&#x8FDE;&#x63A5;&#x7528;&#x4E8E;&#x4E0B;&#x8F7D;            FtpWebRequest req = FtpWebRequest.Create(new Uri(&quot;ftp://127.0.0.1/AB/PC/&quot; + fileName)) as FtpWebRequest;            //2.&#x8BBE;&#x7F6E;&#x4E00;&#x4E2A;&#x901A;&#x4FE1;&#x51ED;&#x8BC1;&#xFF0C;&#x8FD9;&#x6837;&#x624D;&#x80FD;&#x4E0B;&#x8F7D;            //&#x5982;&#x679C;&#x6709;&#x533F;&#x540D;&#x8D26;&#x53F7;&#xFF0C;&#x53EF;&#x4EE5;&#x4E0D;&#x8BBE;&#x7F6E;&#x51ED;&#x8BC1;&#xFF0C;&#x4F46;&#x5B9E;&#x9645;&#x5F00;&#x53D1;&#x4E2D;&#xFF0C;&#x4E0D;&#x8981;&#x4F7F;&#x7528;&#x533F;&#x540D;&#x8D26;&#x53F7;&#xFF0C;&#x4E0D;&#x7136;&#x6709;&#x5B89;&#x5168;&#x9690;&#x60A3;            NetworkCredential n = new NetworkCredential(&quot;qwe&quot;, &quot;123000&quot;);            req.Credentials = n;            //3.&#x5176;&#x4ED6;&#x8BBE;&#x7F6E;            req.Proxy = null;//&#x8BBE;&#x7F6E;&#x4EE3;&#x7406;&#x4E3A;&#x7A7A;            req.KeepAlive = false;//&#x8BF7;&#x6C42;&#x5B8C;&#x6BD5;&#x540E;&#xFF0C;&#x662F;&#x5426;&#x5173;&#x95ED;&#x63A7;&#x5236;&#x8FDE;&#x63A5;            req.Method = WebRequestMethods.Ftp.DownloadFile;//&#x64CD;&#x4F5C;&#x547D;&#x4EE4;-&#x4E0A;&#x4F20;            req.UseBinary = true;//&#x6307;&#x5B9A;&#x4F20;&#x8F93;&#x7684;&#x7C7B;&#x578B;-2&#x8FDB;&#x5236;            //4.&#x4E0B;&#x8F7D;&#x6587;&#x4EF6;            FtpWebResponse res = req.GetResponse() as FtpWebResponse;            Stream downFileStream = res.GetResponseStream();//ftp&#x7684;&#x6D41;&#x5BF9;&#x8C61;            using (FileStream file = File.Create(localPath))            {                //&#x4E00;&#x70B9;&#x4E00;&#x70B9;&#x4E0B;&#x8F7D;                byte[] bytes = new byte[2048];                //&#x8BFB;&#x53D6;&#x4E86;&#x591A;&#x5C11;&#x5B57;&#x8282;                int contentLength = downFileStream.Read(bytes, 0, bytes.Length);                //&#x5FAA;&#x73AF;&#x4E0B;&#x8F7D;&#x6587;&#x4EF6;                while (contentLength != 0)                {                    //&#x5199;&#x5165;&#x5230;&#x672C;&#x5730;&#x6587;&#x4EF6;&#x6D41;&#x4E2D;                    file.Write(bytes, 0, contentLength);                    //&#x5199;&#x5B8C;&#x518D;&#x8BFB;                    contentLength = downFileStream.Read(bytes, 0, bytes.Length);                }                //&#x5FAA;&#x73AF;&#x5B8C;&#x6BD5;&#x540E;&#xFF0C;&#x4E0B;&#x8F7D;&#x5B8C;&#x6BD5;                file.Close();                downFileStream.Close();                res.Close();            }            return true;        }        catch (Exception ex)        {            Debug.Log(fileName + &quot;&#x4E0B;&#x8F7D;&#x5931;&#x8D25; &quot; + ex.Message);            return false;        }        return true;    }    private void OnDestroy()    {        instance = null;    }    //AB&#x5305;&#x4FE1;&#x606F;&#x7C7B;    private class ABInfo    {        public string md5;        public string name;        public long size;        public ABInfo(string name, string size, string md5)        {            this.name = name;            this.size = long.Parse(size);            this.md5 = md5;        }    }}
