using System.IO;using UnityEditor;using UnityEngine;public class MoveABToSA{    [MenuItem(&quot;Tool/&#x79FB;&#x52A8;&#x9009;&#x4E2D;&#x8D44;&#x6E90;&#x5230;StreamingAssets&quot;)]    private static void MoveABToStreamingAssets()    {        //&#x901A;&#x8FC7;Selction&#x7C7B;&#x7684;&#x65B9;&#x6CD5;&#xFF0C;&#x83B7;&#x53D6;&#x9009;&#x4E2D;&#x7684;&#x8D44;&#x6E90;        Object[] selectedAssets = Selection.GetFiltered(typeof(Object), SelectionMode.DeepAssets);        if (selectedAssets.Length == 0) return;        string abCompareInfo = &quot;&quot;;        foreach (Object assset in selectedAssets)        {            //&#x901A;&#x8FC7;AssetDatabase&#x7C7B;&#x83B7;&#x53D6;&#x8D44;&#x6E90;&#x7684;&#x8DEF;&#x5F84;            string assetPath = AssetDatabase.GetAssetPath(assset);            //&#x622A;&#x53D6;&#x8DEF;&#x5F84;&#x5F53;&#x4E2D;&#x7684;&#x6587;&#x4EF6;&#x540D;&#xFF0C;&#x7528;&#x4E8E;&#x4F5C;&#x4E3A;StreamingAssets&#x4E2D;&#x7684;&#x6587;&#x4EF6;&#x540D;            string fileName = assetPath.Substring(assetPath.LastIndexOf(&apos;/&apos;));            //&#x5224;&#x65AD;&#x662F;&#x5426;&#x6709;.&#x7B26;&#x53F7;&#xFF0C;&#x5982;&#x679C;&#x6709;&#xFF0C;&#x8BC1;&#x660E;&#x6709;&#x540E;&#x7F00;&#xFF0C;&#x4E0D;&#x5904;&#x7406;            if (fileName.IndexOf(&apos;.&apos;) != -1) continue;            //&#x5229;&#x7528;AssetDatabase&#x7C7B;&#x7684;&#x65B9;&#x6CD5;&#xFF0C;&#x590D;&#x5236;&#x6587;&#x4EF6;&#x5230;StreamingAssets&#x76EE;&#x5F55;&#x4E0B;            AssetDatabase.CopyAsset(assetPath, &quot;Assets/StreamingAssets/&quot; + fileName);            //&#x83B7;&#x53D6;&#x62F7;&#x8D1D;&#x5230;StreamingAssets&#x6587;&#x4EF6;&#x4E0B;&#x7684;&#x6587;&#x4EF6;&#x7684;&#x4FE1;&#x606F;            FileInfo fileInfo = new FileInfo(Application.streamingAssetsPath + &quot;/&quot; + fileName);            abCompareInfo += fileInfo.Name + &quot; &quot; + fileInfo.Length + &quot; &quot; + CreateABCompare.getfileMd5(fileInfo.FullName);            abCompareInfo += &quot;|&quot;;        }        abCompareInfo = abCompareInfo.Substring(0, abCompareInfo.Length - 1);        File.WriteAllText(Application.streamingAssetsPath + &quot;/ABCompareInfo.txt&quot;, abCompareInfo);        AssetDatabase.Refresh();    }}
