ure)    {        var tp = new BtParallel(success, failure);        AddBehavior(tp);        return this;    }    public BehaviorTreeBuilder Monitor(BtParallel.Policy success, BtParallel.Policy failure)    {        var tp = new BtMonitor(success, failure);        AddBehavior(tp);        return this;    }    public BehaviorTreeBuilder ActiveSelector()    {        var tp = new BtActiveSelector();        AddBehavior(tp);        return this;    }    public BehaviorTreeBuilder Repeat(int limit)    {        var tp = new BtRepeat(limit);        AddBehavior(tp);        return this;    }    public BehaviorTreeBuilder Inverter()    {        var tp = new BtInverter();        AddBehavior(tp);        return this;    }    public BehaviorTreeBuilder DebugNode(string word)    {        var node = new DebugNode(word);        AddBehavior(node);        return this;    }    public void OnDisable()    {        nodeStack.Clear();    }}
