), transform.rotation, LayerMask.GetMask(&quot;Enemy&quot;));                if (col.Length != 0)                {                    currentEnemy = col[0].transform;                    isLockOn = true;                }            }            else            {                UnLock();            }        }        //&#x8DDD;&#x79BB;&#x592A;&#x8FDC;&#xFF0C;&#x81EA;&#x52A8;&#x89E3;&#x9664;&#x9501;&#x5B9A;        if (currentEnemy != null)        {            if (Vector3.Distance(LookAttarGet.position, currentEnemy.position) &gt; escapeDistance)            {                UnLock();            }        }    }    private void UnLock()    {        currentEnemy = null;        isLockOn = false;    }    private void OnDrawGizmos()    {        //Vector3 tempPosition = LookAttarGet.transform.position;        //Vector3 center = tempPosition + new Vector3(0, 1.0f, 0) + transform.forward * 5.0f;        //Gizmos.DrawCube(center, new Vector3(10f, 5f, 10f));    }    private void Update()    {        GetCameraControllerInput();//&#x8BA1;&#x7B97;        LockEnemy();//&#x9009;&#x62E9;&#x9501;&#x5B9A;&#x7684;&#x654C;&#x4EBA;    }    private void LateUpdate()    {        ControllerCamera();//&#x79FB;&#x52A8;&#x6444;&#x50CF;&#x5934;        CameraLockOnTarget();//&#x9501;&#x5B9A;&#x654C;&#x4EBA;    }}

