class Solution {public:    void merge(vector&lt;int&gt;&amp; nums1, int m, vector&lt;int&gt;&amp; nums2, int n) {        vector&lt;int&gt; temp;        for (int q = 0; q &lt; m; q++)            temp.push_back(nums1[q]);        int i = 0;        int j = 0;        int k = 0;        while (i &lt; m &amp;&amp; j &lt; n) {            if (temp[i] &lt; nums2[j])                nums1[k++] = temp[i++];            else                nums1[k++] = nums2[j++];        }        while (i &lt; m)            nums1[k++] = temp[i++];        while (j &lt; n)            nums1[k++] = nums2[j++];    }};
