class Solution {public:    void turnOver(vector&lt;int&gt;&amp; nums, int start, int end) {        while (start != end &amp;&amp; start &lt; end) {            int temp = nums[start];            nums[start] = nums[end];            nums[end] = temp;            start++;            end--;        }    }    void rotate(vector&lt;int&gt;&amp; nums, int k) {        if (nums.size() &lt; 2)            return;        k = k % nums.size();        turnOver(nums, nums.size() - k, nums.size() - 1);        turnOver(nums, 0, nums.size() - k - 1);        turnOver(nums, 0, nums.size() - 1);    }};
