class Solution {public:    int maxProfit(vector&lt;int&gt;&amp; prices) {        int size = prices.size();        int min = INT_MAX;        int max = INT_MIN;        for (int i = 0; i &lt; size; i++) {            if (prices[i] &lt; min) {                min = prices[i];            } else if (max &lt; prices[i] - min) {                max = prices[i] - min;            }        }        if (max == INT_MIN)            return 0;        return max;    }};
